<script setup>
import {computed} from 'vue';import {useAppointmentStore} from '../../stores/appointments';import {formatDate} from '../../utils/appointmentDates';import AppointmentStatusBadge from './AppointmentStatusBadge.vue';
const props=defineProps({today:String,filters:Object});defineEmits(['filter','open','page']);const store=useAppointmentStore();const all=computed(()=>Object.values(store.summary).reduce((a,b)=>a+Number(b),0));
</script>
<template><aside class="clinic-panel appointment-today"><div class="clinic-card-heading"><h2>Today</h2><time>{{formatDate(today,{weekday:'short',month:'short',day:'numeric'})}}</time></div><div class="appointment-today-stats"><div><strong>{{all}}</strong><small>Appointments</small></div><div><strong>{{store.summary.checked_in||0}}</strong><small>Checked In</small></div><div><strong>{{store.summary.in_consultation||0}}</strong><small>In Consultation</small></div><div><strong>{{store.summary.completed||0}}</strong><small>Completed</small></div></div><h3 class="appointment-panel-tab">Appointments</h3><div class="appointment-status-filters"><button :class="{'selected':!filters.status}" @click="$emit('filter',{status:''})">All<strong>{{all}}</strong></button><button v-for="([label,color],status) in store.options?.statuses" :key="status" :class="[`appointment-color-${color}`,{'selected':filters.status===status}]" @click="$emit('filter',{status:filters.status===status?'':status})">{{label}}<strong>{{store.summary[status]||0}}</strong></button></div><details class="appointment-today-filters" open><summary>Filters</summary><div><label class="field">Visit type<select :value="filters.appointment_type_id" @change="$emit('filter',{appointment_type_id:$event.target.value})"><option value="">All types</option><option v-for="t in store.options?.types" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label class="field">Status<select :value="filters.status" @change="$emit('filter',{status:$event.target.value})"><option value="">All statuses</option><option v-for="([label],key) in store.options?.statuses" :key="key" :value="key">{{label}}</option></select></label></div></details><h3 class="appointment-today-title">Today's Appointments</h3><button v-for="a in store.todayRows" :key="a.id" class="appointment-today-row" @click="$emit('open',a)"><time>{{a.starts_at.slice(11,16)}}<small>{{a.ends_at.slice(11,16)}}</small></time><div><strong>{{a.patient.full_name}}</strong><small>{{a.type || 'Appointment'}}</small><small>{{a.doctor.full_name}}</small></div><AppointmentStatusBadge :status="a.status"/></button><p v-if="!store.todayRows.length" class="empty-state">{{all?'No appointments match these filters today.':'No appointments today.'}}</p><div v-if="store.todayMeta?.last_page>1" class="patient-pagination"><button :disabled="store.todayMeta.current_page===1" @click="$emit('page',store.todayMeta.current_page-1)">Previous</button><span>{{store.todayMeta.current_page}} / {{store.todayMeta.last_page}}</span><button :disabled="store.todayMeta.current_page===store.todayMeta.last_page" @click="$emit('page',store.todayMeta.current_page+1)">Next</button></div></aside></template>
